package app.thawani

internal fun cards2(): List<Card> = listOf(
Card("p7","first_aid","طوارئ هبوط وارتفاع السكر الحاد (قاعدة 15-15)","997","طوارئ أيضية — خطر فقدان الوعي","w","إذا اشتبهت بهبوط السكر ولم يتوفر جهاز فحص، عالجه فوراً كأنه هبوط سكر؛ فهبوط السكر الحاد يهدد الدماغ خلال دقائق بينما الارتفاع المؤقت أقل خطورة.",listOf("إذا كان المصاب واعياً ويستطيع البلع بأمان: طبّق (قاعدة 15) بإعطائه 15 جراماً من السكر سريع الامتصاص (نصف كوب عصير محلى، أو ملعقة كبيرة عسل/سكر مذاب في ماء).","انتظر 15 دقيقة في وضع الراحة، ثم أعد قياس السكر؛ إذا ظل أقل من 70 ملجم/ديسيلتر كرر إعطائه 15 جراماً أخرى.","بمجرد ارتفاع السكر فوق 70 وتحسن الأعراض: أعطه وجبة خفيفة تحتوي على نشويات وبروتين (مثل شطيرة جبن أو تمر مع لبن) لمنع تكرار الهبوط.","إذا كان المصاب فاقداً للوعي أو عاجزاً عن البلع: ضعه في وضعية الإفاقة على جانبه واتصل بـ 997 فوراً.","إذا توفرت حقنة الجلوكاجون الطارئة أو بخاخ الجلوكاجون الأنفي وكنت مدرباً عليها، استخدمها فوراً للمصاب الغائب عن الوعي."),listOf("لا تحاول سكب العصير أو الماء أو وضع الطعام في فم مريض السكر الغائب عن الوعي حتى لا يختنق.","لا تعطِ الشوكولاتة أو الحليب كامل الدسم كخيار أول لرفع السكر السريع لأن الدهون تبطئ امتصاص السكر.","لا تحقن الإنسولين أبداً لمريض فاقد للوعي لأن ذلك قد يكون قاتلاً إذا كانت الحالة هبوطاً بالسكر."),listOf("أعراض الهبوط: رجفة، تعرق بارد غزير، شحوب، جوع شديد، تسارع نبض، تشوش ذهني أو عصبية مفاجئة."),listOf("البيت","المدرسة","الاستراحة","التخييم","السفر"),listOf(Link("وزارة الصحة: انخفاض السكر","https://www.moh.gov.sa/healthawareness/educationalcontent/diseases/diabetic/pages/hypoglycemia-low-blood-glucose-levels.aspx")),listOf()),
Card("p8","first_aid","نوبات التشنج والصرع","997","حماية المصاب من الإصابات وتأمين التنفس","t","خرافة (بلع اللسان) غير صحيحة علمياً أثناء التشنج؛ لا تفتح فم المصاب بالقوة ولا تضع أي أداة أو إصبع داخل فمه أبداً.",listOf("حافظ على هدوئك، واحسب وقت بدء النوبة بالساعة، وأبعد الأثاث أو الأدوات الحادة من حول المصاب.","ضع وسادة أو قطعة ملابس مطوية ناعمة تحت رأس المصاب لحمايته من الارتطام بالأرض.","فكّ أزرار الياقة أو ربطة العنق أو النظارة لتسهيل التنفس.","بمجرد انتهاء الحركات التشنجية: أدر المصاب برفق على أحد جانبيه (وضعية الإفاقة) ليخرج اللعاب ويبقى مجرى الهواء مفتوحاً.","ابقَ بجانبه وتحدث معه بهدوء حتى يستعيد وعيه الكامل، واتصل بـ 997 إذا استمرت النوبة أكثر من 5 دقائق."),listOf("لا تثبّت المصاب بالقوة ولا تحاول إيقاف حركات أطرافه أثناء التشنج لتجنب كسر العظام أو خلع المفاصل.","لا تضع ملعقة أو قماشاً أو أصابعك في فم المصاب تحت أي ظرف.","لا تعطِ المصاب ماءً أو دواءً أو طعاماً إلا بعد أن يستيقظ تماماً ويعود لوعيه الكامل."),listOf("الحالات التي تستوجب الإسعاف الفوري (997): استمرار النوبة أكثر من 5 دقائق، أو تكرر نوبتين متتاليتين دون إفاقة، أو حدوثها لأول مرة."),listOf("البيت","المدرسة","الاستراحة","التخييم","السفر"),listOf(Link("وزارة الصحة: التشنجات","https://www.moh.gov.sa/healthawareness/educationalcontent/firstaid/pages/010.aspx")),listOf(Link("إسعاف المصاب بنوبة صرع · الهلال الأحمر السعودي","https://youtu.be/55dtD1afVK8"))),
Card("p9","first_aid","الكسور وإصابات الرأس والعمود الفقري","997","حرج — منع المضاعفات العصبية والشلل","t","عند الشك بإصابة في الرأس أو الرقبة أو الظهر (بعد سقوط من علو أو حادث مروري): لا تحرّك المصاب أبداً إلا إذا كان هناك خطر فوري كحريق.",listOf("ثبّت رأس ورقبة المصاب في نفس وضعيتها بوضع يديك على جانبي رأسه لمنع أي التفات ريثما يصل الهلال الأحمر (997).","للكسور في الأطراف: لا تحاول إرجاع العظم المكسور إلى مكانه؛ ثبّت الطرف في الوضع الذي وجدته عليه باستخدام جبيرة مؤقتة (كرتون مقوى أو لوح خشبي مبطن).","إذا كان الكسر مفتوحاً (خروج العظم من الجلد): غطِّ الجرح بشاش معقم واضغط حول حواف الجرح للسيطرة على النزيف دون الضغط على العظم البارز.","ضع كمادات باردة ملفوفة بقماش فوق منطقة الكسر المغلق لتقليل التورم والألم.","افحص النبض والإحساس ولون الأصابع في الطرف المصاب قبل وبعد وضع الجبيرة للتأكد من عدم شدها أكثر من اللازم."),listOf("لا تنقل مصاب الحوادث أو السقوط في سيارة خاصة بطريقة عشوائية قد تقطع الحبل الشوكي.","لا تنزع خوذة سائق الدراجة المصاب إلا إذا كان لا يتنفس واستحال فتح مجرى الهواء."),listOf("علامات ارتجاج الدماغ الخطيرة: قيء متكرر، تفاوت حجم حدقتي العين، خروج سائل شفاف أو دم من الأذن/الأنف، ميل شديد للنوم."),listOf("البيت","المدرسة","الاستراحة","التخييم","السفر"),listOf(Link("وزارة الصحة: الكسور","https://www.moh.gov.sa/healthawareness/educationalcontent/firstaid/pages/007.aspx"),Link("وزارة الصحة: إصابات الرأس","https://www.moh.gov.sa/healthawareness/educationalcontent/firstaid/pages/008.aspx")),listOf()),
Card("p10","first_aid","نزيف الأنف الحاد (الرعاف)","937","إسعاف أولي شائع — تصحيح الخطأ الشائع","p","أمِل الرأس للأمام قليلاً وليس للخلف أبداً؛ فإرجاع الرأس للخلف يجعل الدم ينزل للحلق والمعدة مما يسبب القيء أو الاختناق.",listOf("أجلس المصاب في وضع مستقيم مع إمالة رأسه للأمام قليلاً واطلب منه التنفس بهدوء عن طريق الفم.","اضغط بإصبعي الإبهام والسبابة على الجزء الغضروفي اللين من الأنف (أسفل العظمة مباشرة) بقوة وثبات.","استمر بالضغط المتواصل لمدة 10 إلى 15 دقيقة كاملة حسب الساعة دون رفع أصابعك كل دقيقة للتأكد.","ضع كمادة باردة أو كيس ثلج ملفوفاً بقماش فوق جسر الأنف والجبهة للمساعدة في انقباض الأوعية الدموية.","بعد توقف النزيف، اطلب من المصاب عدم التمخط أو فرك الأنف أو الانحناء لعدة ساعات."),listOf("لا تُرجع رأس المصاب للخلف ولا تجعله يستلقي على ظهره أثناء الرعاف.","لا تحشُ الأنف بالمناديل الورقية أو القطن الجاف لأنه يلتصق بالجلطة الدموية ويعيد فتح الجرح عند سحبه."),listOf("راجع الطوارئ فوراً إذا استمر النزيف أكثر من 20 دقيقة رغم الضغط الصحيح، أو إذا كان المصاب يتناول مسيلات الدم."),listOf("البيت","المدرسة","الاستراحة","التخييم","السفر"),listOf(Link("وزارة الصحة: نزيف الأنف (الرعاف)","https://www.moh.gov.sa/healthawareness/educationalcontent/firstaid/pages/014.aspx")),listOf(Link("سلسلة الإسعافات الأولية · وزارة الصحة السعودية","https://www.youtube.com/playlist?list=PLv4VVZM1QJ17E1LCQ7h1917ZuHUjXft0_"))),
Card("p11","first_aid","إصابات العين والمواد الكيميائية","997","طوارئ عيون — الغسل الفوري وعدم الفرك","w","في إصابات العين الكيميائية: اغسل العين فوراً بماء الصنبور الجاري لمدة 15-20 دقيقة متواصلة؛ وفي الأجسام المغروسة: لا تفرك العين ولا تسحب الجسم المغروس أبداً.",listOf("عند دخول مادة كيميائية (منظف/معقم/كلور): افتح جفني العين برفق واغسلها بماء جارٍ فاتر لمدة 15 دقيقة بحيث يتدفق الماء من الزاوية الداخلية للخارجية (حتى لا تتلوث العين السليمة).","انزع العدسات اللاصقة فوراً أثناء الغسل بالماء إذا كانت موجودة.","عند وجود ذرة غبار سطحية: ارمش عدة مرات أو اغسل العين بمحلول ملحي معقم دون فركها.","عند انغراس جسم صلب أو شظية في العين: لا تحاول إزالته أبداً؛ غطِّ العين المصابة بكوب ورقي مفرغ (حتى لا يضغط على الجفن) وغطِّ العين السليمة أيضاً لمنع حركة العينين معاً.","توجه لطوارئ العيون فوراً أو اتصل بـ 997."),listOf("لا تفرك العين المصابة بيدك تحت أي ظرف لأن الفرك يخدش القرنية بعمق.","لا تستخدم قطرات عيون علاجية أو ملونة قبل فحص الطبيب."),listOf("أخذ عبوة المادة الكيميائية أو تصويرها لإطلاع طبيب العيون على تركيبها الكيميائي."),listOf("البيت","المدرسة","الاستراحة","التخييم","السفر"),listOf(Link("وزارة الصحة: إصابات العين","https://www.moh.gov.sa/healthawareness/educationalcontent/firstaid/pages/013.aspx")),listOf()),
Card("p12","first_aid","الإغماء المفاجئ ووضعية الإفاقة","997","إسعاف أولي — تأمين مجرى الهواء والتروية الدموية","p","إذا كان الشخص فاقداً للوعي ولكنه يتنفس بشكل طبيعي، فإن وضعية الإفاقة (على الجانب) هي الوضع الآمن لمنع انسداد مجرى الهواء باللسان أو القيء.",listOf("افحص استجابة المصاب وتأكد أولاً أنه يتنفس طبيعياً (إذا كان لا يتنفس انتقل فوراً لبروتوكول الإنعاش القلبي CPR).","إذا كان الإغماء بسيطاً وبدأ يستعيد وعيه سريعاً: دعه مستلقياً على ظهره وارفع ساقيه بزاوية 30 درجة لإعادة الدم للدماغ.","فكّ الملابس الضيقة حول الرقبة والحزام، ووفّر تهوية جيدة في المكان.","إذا استمر غيابه عن الوعي مع وجود تنفس طبيعي: ضعه في (وضعية الإفاقة) بإمالته على جانبه، ووضع يده العليا تحت خده، وثني ركبته العليا بزاوية قائمة.","لا تسمح له بالوقوف السريع فور إفاقته؛ أبقِه جالساً لـ 10 دقائق، واتصل بـ 997 إذا لم يفق خلال دقيقة واحدة."),listOf("لا تصفع وجه المصاب ولا ترش الماء البارد على وجهه ولا تقرب العطور النفاذة أو البصل من أنفه.","لا ترفع رأس المصاب بوسادة عالية أثناء الإغماء لأن ذلك يقلل وصول الدم للدماغ."),listOf("عند الشعور بدوخة ما قبل الإغماء: اجلس فوراً أو استلقِ وضع رأسك بين ركبتيك لتفادي السقوط والارتطام."),listOf("البيت","المدرسة","الاستراحة","التخييم","السفر"),listOf(Link("وزارة الصحة: إرشادات فقدان الوعي","https://www.moh.gov.sa/ministry/mediacenter/news/pages/news-2013-02-03-004.aspx")),listOf())
)
